<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\TruckService;use App\Support\Url;Auth::requirePermission('TRUCK_VIEW_OWN');$rows=TruckService::allOwn();$pageTitle='My Trucks';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>My trucks</h1><p>Owner-scoped truck and compliance records.</p></div><?php if(Auth::can('TRUCK_CREATE_OWN')):?><a class="button" href="<?=h(Url::to('carrier/trucks/create.php'))?>">Register truck</a><?php endif;?></div><div class="card table-wrap"><table><thead><tr><th>Registration</th><th>Truck</th><th>Body</th><th>Capacity</th><th>Verification</th><th>Availability</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['registration_number'].' · '.$r['registration_country'])?></td><td><?=h($r['make_name'].' '.$r['model_name'])?></td><td><?=h(str_replace('_',' ',$r['body_type_code']))?></td><td><?=h($r['capacity_value'].' '.$r['capacity_unit'])?></td><td><span class="status-pill"><?=h($r['verification_status'])?></span></td><td><?=h($r['availability_status'])?></td><td><a href="<?=h(Url::to('carrier/trucks/view.php?id='.$r['truck_id']))?>">View</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No trucks registered.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
